const MAX_ATTEMPTS = 3;

const REQUIRED_CRITERIA = [
  'sharpness',
  'blur',
  'pixelation',
  'compression_artifacts',
  'upscaling_artifacts',
  'digital_noise',
  'over_smoothing',
  'over_sharpening',
  'color_banding',
  'aliasing',
  'moire_pattern',
  'clipping',
  'color_artifacts',
  'ai_artifacts',
  'fine_detail_legibility',
  'visual_consistency'
];

// Get the original image context and binary files
const original = $('AI Source').first();
const response = $input.first().json;

// Each sub-workflow processes exactly one original image
const attempt = $runIndex + 1;

const errors = [];
let report = null;

// Check whether a value is a plain JSON object
function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

// Check whether a value is a non-empty string
function isNonEmptyString(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

// Extract the model's text response
const parts =
  response.content?.parts ??
  response.candidates?.[0]?.content?.parts ??
  [];

let responseText = parts
  .filter(part => typeof part.text === 'string')
  .map(part => part.text)
  .join('\n')
  .trim();

// Remove optional Markdown code fences
responseText = responseText
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// Parse the JSON without stopping the workflow
if (!responseText) {
  errors.push('Missing response text');
} else {
  try {
    report = JSON.parse(responseText);
  } catch (error) {
    errors.push(`Invalid JSON: ${error.message}`);
  }
}

// Validate the response structure
if (report !== null) {

  if (!isObject(report)) {
    errors.push('Response must be a JSON object');
  } else {

    // Validate original image identity
    if (report.job_id !== original.json.job_id) {
      errors.push('Job ID does not match the source image');
    }

    if (report.file !== original.json.file) {
      errors.push('Filename does not match the source image');
    }

    // Validate overall verdict
    const validVerdicts = ['PASS', 'REVIEW', 'FAIL'];

    if (!validVerdicts.includes(report.overall_verdict)) {
      errors.push('Invalid overall_verdict');
    }

    // Validate confidence
    const validConfidence = ['high', 'medium', 'low'];

    if (!validConfidence.includes(report.confidence)) {
      errors.push('Invalid confidence value');
    }

    // Validate summary and recommendation
    if (!isNonEmptyString(report.summary)) {
      errors.push('Missing or empty summary');
    }

    if (!isNonEmptyString(report.recommendation)) {
      errors.push('Missing or empty recommendation');
    }

    // Validate list of important issues
    if (!Array.isArray(report.important_issues)) {
      errors.push('important_issues must be an array');
    } else if (
      report.important_issues.some(
        issue => !isNonEmptyString(issue)
      )
    ) {
      errors.push('Invalid important_issues entry');
    }

    // Validate all 16 evaluation criteria
    if (!isObject(report.criteria)) {
      errors.push('Missing or invalid criteria object');
    } else {

      for (const criterion of REQUIRED_CRITERIA) {

        const result = report.criteria[criterion];

        if (!isObject(result)) {
          errors.push(`Missing criterion: ${criterion}`);
          continue;
        }

        // Scores must be integers from 0 to 5
        if (
          !Number.isInteger(result.score) ||
          result.score < 0 ||
          result.score > 5
        ) {
          errors.push(
            `Invalid score for ${criterion}`
          );
        }

        // Every criterion must have an explanation
        if (!isNonEmptyString(result.comment)) {
          errors.push(
            `Missing comment for ${criterion}`
          );
        }
      }

      // Reject unexpected criteria
      const unexpectedCriteria = Object.keys(
        report.criteria
      ).filter(
        criterion => !REQUIRED_CRITERIA.includes(criterion)
      );

      if (unexpectedCriteria.length > 0) {
        errors.push(
          'Unexpected criteria: ' +
          unexpectedCriteria.join(', ')
        );
      }
    }
  }
}

// Determine whether the response is structurally valid
const isValid = errors.length === 0;

// Preserve source metadata for the next step
const result = {
  json: {
    ...original.json,

    validation_status: isValid ? 'VALID' : 'INVALID',
    attempt,
    max_attempts: MAX_ATTEMPTS,

    validation_errors: errors,

    ai_report: isValid ? report : null
  },

  pairedItem: { item: 0 }
};

// Restore the original four images only when needed
if (!isValid) {
  if (!original.binary) {
    throw new Error('Original image binaries are missing');
  }

  result.binary = original.binary;
}

return [result];

return $input.all().map((item, index) => {

  const data = item.json;
  const isValid = data.validation_status === 'VALID';

  return {
    json: {
      job_id: data.job_id,
      file: data.file,

      print_specification: data.print_specification,
      technical_validation: data.technical_validation,

      ai_validation: {
        execution_status: isValid ? 'COMPLETED' : 'ERROR',
        attempts: data.attempt,

        verdict: isValid
          ? data.ai_report.overall_verdict
          : null,

        report: isValid
          ? data.ai_report
          : null,

        validation_errors: isValid
          ? []
          : data.validation_errors
      }
    },

    pairedItem: { item: index }
  };
});

const MAX_API_ATTEMPTS = 4;

// Get the original image metadata and binary files
const original = $('AI Source').first();

// Get the Gemini API error
const response = $input.first().json;
const error = response.error ?? response;

// Count API failures in the current sub-workflow
const attempt = $runIndex + 1;

// Extract the error message
const message = typeof error === 'string'
  ? error
  : String(
      error.message ??
      error.description ??
      response.message ??
      response.description ??
      'Unknown Gemini API error'
    );

// Extract the HTTP status code
const rawStatus =
  error.statusCode ??
  error.httpCode ??
  error.code ??
  response.statusCode ??
  null;

const statusCode = Number(rawStatus);

// Identify temporary API errors
const retryableCodes = [408, 429, 500, 502, 503, 504];

const retryable =
  retryableCodes.includes(statusCode) ||
  /service unavailable|high demand|temporarily unavailable|timeout|timed out|resource exhausted/i
    .test(message);

// Avoid retrying clearly permanent quota errors
const permanentQuotaError =
  /daily quota|quota per day|billing required/i.test(message);

const shouldRetry =
  retryable &&
  !permanentQuotaError &&
  attempt < MAX_API_ATTEMPTS;

// Calculate exponential retry delay
const waitSeconds = shouldRetry
  ? Math.min(30 * Math.pow(2, attempt - 1), 120)
  : 0;

// Prepare the retry or error result
const result = {
  json: {
    ...original.json,

    api_attempt: attempt,
    api_should_retry: shouldRetry,
    api_wait_seconds: waitSeconds,

    api_error: {
      status_code: Number.isFinite(statusCode)
        ? statusCode
        : null,
      message
    },

    // Keep compatibility with the existing finalizer
    validation_status: 'API_ERROR',
    attempt,
    max_attempts: MAX_API_ATTEMPTS,
    validation_errors: [
      `Gemini API error: ${message}`
    ],
    ai_report: null
  },

  pairedItem: { item: 0 }
};

// Restore all four images for the next API request
if (shouldRetry) {
  if (!original.binary) {
    throw new Error('Original image binaries are missing');
  }

  result.binary = original.binary;
}

return [result];
